  "fr-1549": {
    "kind": "association",
    "text": "lunettes 的构词本来是“小月亮”，后来用于眼镜；-ette 是小称词尾，这一联系有词典依据。",
    "origin": {
      "text": "法兰西学院词典把 lunette 记为 lune（月亮）的小称形式。现代复数 lunettes 指眼镜；-ette 是这里可辨认的小称词尾。",
      "sources": [
        {
          "label": "法兰西学院词典",
          "url": "https://www.dictionnaire-academie.fr/article/A9L1359"
        }
      ]
    }
  },
  "fr-1550": {
    "kind": "playful",
    "text": "montre 借 monitor（监视器）的 mon：把看时间的小屏幕绑上手腕，就是手表。"
  },
  "fr-1551": {
    "kind": "playful",
    "text": "repas 开头像 repeat（重复）：早上吃过，中午 repeat，晚上又 repeat，一顿接一顿。"
  },
  "fr-1552": {
    "kind": "playful",
    "text": "petit（小）＋ déjeuner（午餐）：把午餐缩成小一份，提前到起床后吃，变成早餐。"
  },
  "fr-1553": {
    "kind": "playful",
    "text": "déjeuner 抓住 je，借“借”：同事到中午问“借你饭卡刷一下”，午餐时间到了。"
  },
  "fr-1554": {
    "kind": "english",
    "text": "dinner"
  },
  "fr-1555": {
    "kind": "playful",
    "text": "faim 像 famine（饥荒）被压短了：肚子里已经闹起小小的 famine，饿得咕咕叫。"
  },
  "fr-1556": {
    "kind": "playful",
    "text": "soif 抓住 soi，借 soda（汽水）：口干得只盯着冰柜里的 soda，先喝一大口。"
  },
  "fr-1557": {
    "kind": "english",
    "text": "nourish（滋养）作线索；nourriture 保留 nourri-，表示供人吃的食物。"
  },
  "fr-1558": {
    "kind": "association",
    "text": "plat 作形容词是平的；平盘上端来一道菜。"
  },
  "fr-1559": {
    "kind": "english",
    "text": "menu；法语餐厅也常指固定套餐"
  },
  "fr-1560": {
    "kind": "english",
    "text": "wine；也可联想英语 vino"
  },
  "fr-1561": {
    "kind": "english",
    "text": "beer"
  },
