  "fr-1690": {
    "kind": "english",
    "text": "agency"
  },
  "fr-1691": {
    "kind": "english",
    "text": "boutique"
  },
  "fr-1692": {
    "kind": "playful",
    "text": "bâtiment 中间有 tim，借 timber（木材）：一根根 timber 拼起来，慢慢盖成一栋建筑。"
  },
  "fr-1693": {
    "kind": "playful",
    "text": "usine 像 using（正在用）换了尾巴：流水线不停 using 机器，整座工厂都在运转。"
  },
  "fr-1694": {
    "kind": "english",
    "text": "university"
  },
  "fr-1695": {
    "kind": "playful",
    "text": "lycée 借“理科”：高中选文科还是理科？先把这段选课烦恼钉在高中上。"
  },
  "fr-1696": {
    "kind": "playful",
    "text": "collège 像 college（大学）：学生背着大书包说要去 college，结果校门写“初中”，上大学还早呢。"
  },
  "fr-1697": {
    "kind": "english",
    "text": "crib（婴儿床）与 crèche 有共同的古老词源。crèche 曾指耶稣诞生故事中的马槽，后来用于收托婴幼儿的地方。",
    "origin": {
      "text": "crèche 起初指牲畜的食槽。基督教耶稣诞生叙事中的马槽与婴儿联系起来，后来这个词又用于接收婴幼儿的场所；它与英语 crib 有共同的日耳曼语来路。",
      "sources": [
        {
          "label": "法兰西学院词典",
          "url": "https://www.dictionnaire-academie.fr/article/A9C4856"
        },
        {
          "label": "CNRTL / TLFi",
          "url": "https://www.cnrtl.fr/etymologie/cr%C3%A8che"
        },
        {
          "label": "Etymonline",
          "url": "https://www.etymonline.com/word/crib"
        }
      ]
    }
  },
  "fr-1698": {
    "kind": "playful",
    "text": "roue 抓住 round（圆）的 rou：圆圆一圈装到车上，才转得起来。"
  },
  "fr-1699": {
    "kind": "association",
    "text": "联想英语 pneumatic（充气的）：轮胎里充气。"
  },
  "fr-1700": {
    "kind": "playful",
    "text": "frein 借 freeze（冻结）的 fre：红灯一亮，车像 freeze 一样停住，靠的就是刹车。"
  },
  "fr-1701": {
    "kind": "english",
    "text": "film"
  },
  "fr-1702": {
    "kind": "english",
    "text": "music"
  },
  "fr-1703": {
    "kind": "english",
    "text": "chant（吟唱）和 chanson 都保留 chan-；唱出来的东西就是歌曲。"
  },
  "fr-1704": {
    "kind": "playful",
    "text": "jeu 借“局”：再开一局、最后一局——一听就知道在玩游戏。"
  },
  "fr-1705": {
    "kind": "association",
    "text": "jeu 游戏＋小物件的联想：jouet 是玩具。"
  },
  "fr-1706": {
    "kind": "english",
    "text": "balloon；也可指用来踢的大球"
  },
  "fr-1707": {
    "kind": "english",
    "text": "match"
  },
