  "fr-1988": {
    "kind": "english",
    "text": "chauffeur",
    "origin": {
      "text": "chauffeur 来自 chauffer（加热）。它早先指照管炉火的人，例如为蒸汽机添火的工人，后来又用于汽车司机。今天的司机称呼，仍带着“加热”的词根。",
      "sources": [
        {
          "label": "法兰西学院词典",
          "url": "https://www.dictionnaire-academie.fr/article/A9C1813"
        }
      ]
    }
  },
